sys_script_include.script:
var EventUtilsClient = Class.create();
EventUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEventDetails: function() {
        var eventId = this.getParameter('sysparm_eventId');

        var eventGR = new GlideRecord('x_1790227_event_ma_event');
        if (eventGR.get(eventId)) {
            var eventDetails = {
                event_name: eventGR.getValue('u_event_name'),
                location: eventGR.getValue('u_location'),
                status: eventGR.getValue('u_status')
            };
            return JSON.stringify(eventDetails);
        } else {
            return JSON.stringify({error: 'Event not found'});
        }
    },
	isVIPEvent: function() {
        var eventId = this.getParameter('sysparm_eventId');

        var eventGR = new GlideRecord('x_1790227_event_ma_event');
        if (eventGR.get(eventId)) {
            return eventGR.getValue('u_vip') == true;
        }
        return false;
    },

    type: 'EventUtilsClient'
});
